function validate([nums, l, r]) {
  if (nums.length < 2 || nums.length > 500) return 'nums needs 2 to 500 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1e5 || v > 1e5)) return 'Each value of nums is a whole number from -10^5 to 10^5.';
  if (l.length !== r.length) return 'l and r must have the same length.';
  if (l.length < 1 || l.length > 500) return 'There must be 1 to 500 queries.';
  for (let i = 0; i < l.length; i++) {
    if (!Number.isInteger(l[i]) || !Number.isInteger(r[i]) || l[i] < 0 || l[i] >= r[i] || r[i] >= nums.length) return 'Each query needs 0 <= l[i] < r[i] < n.';
  }
  return null;
}

