function checkArithmeticSubarrays(nums, l, r) {
  const answer = [];
  for (let q = 0; q < l.length; q++) {
    const sorted = nums.slice(l[q], r[q] + 1).sort((a, b) => a - b);
    const step = sorted[1] - sorted[0];
    let arithmetic = true;
    for (let i = 2; i < sorted.length; i++) {
      if (sorted[i] - sorted[i - 1] !== step) {
        arithmetic = false;
        break;
      }
    }
    answer.push(arithmetic);
  }
  return answer;
}

