function checkArithmeticSubarrays(nums, l, r) {
  // An arithmetic order must run from the minimum to the maximum in equal steps;
  // build those exact terms and match them against the piece's multiset of values.
  return l.map((from, q) => {
    const piece = nums.slice(from, r[q] + 1);
    const low = Math.min(...piece), high = Math.max(...piece), k = piece.length;
    if ((high - low) % (k - 1) !== 0) return false;
    const step = (high - low) / (k - 1);
    const counts = new Map();
    for (const v of piece) counts.set(v, (counts.get(v) || 0) + 1);
    for (let j = 0; j < k; j++) {
      const term = low + j * step;
      if (!counts.get(term)) return false;
      counts.set(term, counts.get(term) - 1);
    }
    return true;
  });
}

