function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 500 : int(2, 10);
  const span = large ? 100000 : 6;
  const nums = Array.from({ length: n }, () => int(-span, span));
  // Lay shuffled arithmetic runs over nums so that many queries can answer true.
  const blocks = [];
  let start = 0;
  while (start < n - 1) {
    const length = Math.min(n - start, large ? int(2, 60) : int(2, 5));
    if (length >= 2 && rand() < (large ? 0.8 : 0.5)) {
      const step = large ? int(-300, 300) : int(-3, 3);
      const lowest = Math.min(0, step * (length - 1)), highest = Math.max(0, step * (length - 1));
      const first = int(-span - lowest, span - highest);
      const run = Array.from({ length }, (_, j) => first + j * step);
      for (let j = run.length - 1; j > 0; j--) { const k = int(0, j); [run[j], run[k]] = [run[k], run[j]]; }
      // Sometimes nudge one value so the run just misses being arithmetic.
      if (length >= 3 && rand() < 0.2) { const j = int(0, length - 1); run[j] += run[j] < span ? 1 : -1; }
      for (let j = 0; j < length; j++) nums[start + j] = run[j];
      blocks.push([start, start + length - 1]);
    }
    start += length;
  }
  const m = large ? 500 : int(1, 6);
  const l = [], r = [];
  for (let q = 0; q < m; q++) {
    if (blocks.length && rand() < 0.5) {
      const [from, to] = blocks[int(0, blocks.length - 1)];
      l.push(from); r.push(to);
    } else {
      const from = int(0, n - 2);
      l.push(from); r.push(int(from + 1, large ? Math.min(n - 1, from + int(1, 200)) : n - 1));
    }
  }
  return [nums, l, r];
}
